const readline = require("node:readline");

function main() {
  const rl = readline.createInterface({ input: process.stdin });

  rl.on("line", (line) => {
    // TODO: parse score, compute passed/perfect/invalid flags, print lines

// Parse score
const score = line.trim();

//Compute
const passed = (Number(score)>=80)
const perfect = (Number(score)===100)
const invalid = !Number.isFinite(score) || !Number(score)<0 || !Number(score)>100

    process.stdout.write("passed: " + `${passed}`);
    process.stdout.write("\nperfect: " + `${perfect}`);
    process.stdout.write("\ninvalid: " + `${invalid}`);
    rl.close();
  });
}

main();

